//! What the `rateLimit` step calls: a sliding window per key, in the memory of the process.
//!
//! The counts are not shared between instances of a service: with several replicas, the real limit is
//! `max` times the number of replicas.
//!
//! @generated by service-builder. Do not edit: changes are overwritten on the next export.

use std::collections::{HashMap, VecDeque};
use std::sync::{LazyLock, Mutex};
use std::time::{Duration, Instant};

use anyhow::Result;

use crate::http::HttpError;

/// How often the keys that went quiet are forgotten, so that the memory does not grow with every key seen.
const SWEEP_EVERY: Duration = Duration::from_secs(60);

struct Entry {
    window: Duration,
    hits: VecDeque<Instant>,
}

pub struct Limiter {
    entries: HashMap<String, Entry>,
    last_sweep: Instant,
}

impl Limiter {
    pub fn new(now: Instant) -> Self {
        Self {
            entries: HashMap::new(),
            last_sweep: now,
        }
    }

    /// Counts an attempt. `Err(wait)`: how long until the oldest attempt of the window expires.
    pub fn check(
        &mut self,
        key: &str,
        max: usize,
        window: Duration,
        now: Instant,
    ) -> Result<(), Duration> {
        if now.duration_since(self.last_sweep) >= SWEEP_EVERY {
            self.entries.retain(|_, e| {
                e.hits
                    .back()
                    .is_some_and(|&t| now.duration_since(t) < e.window)
            });
            self.last_sweep = now;
        }
        let entry = self.entries.entry(key.to_owned()).or_insert_with(|| Entry {
            window,
            hits: VecDeque::new(),
        });
        entry.window = window;
        while entry
            .hits
            .front()
            .is_some_and(|&t| now.duration_since(t) >= window)
        {
            entry.hits.pop_front();
        }
        if entry.hits.len() >= max {
            let oldest = entry.hits.front().copied().unwrap_or(now);
            return Err(window.saturating_sub(now.duration_since(oldest)));
        }
        entry.hits.push_back(now);
        Ok(())
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }
}

static LIMITER: LazyLock<Mutex<Limiter>> = LazyLock::new(|| Mutex::new(Limiter::new(Instant::now())));

/// The step: `scope` is the step, `key` what it counts by (an e-mail, an address). Past `max` attempts in
/// `window_secs`, the answer is a 429 with the seconds to wait in `Retry-After`.
pub fn check(scope: &str, key: &str, max: u32, window_secs: u32) -> Result<()> {
    let key = format!("{scope}\u{1f}{key}");
    let outcome = LIMITER
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .check(
            &key,
            max as usize,
            Duration::from_secs(u64::from(window_secs)),
            Instant::now(),
        );
    outcome.map_err(|wait| {
        HttpError::new(429, "too many attempts, try again later")
            .with_retry_after(wait.as_secs().max(1))
            .into()
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    const MINUTE: Duration = Duration::from_secs(60);

    #[test]
    fn blocks_after_max_then_reopens() {
        let t0 = Instant::now();
        let mut limiter = Limiter::new(t0);
        for i in 0..3 {
            assert!(limiter.check("a", 3, MINUTE, t0 + Duration::from_secs(i)).is_ok());
        }
        let wait = limiter
            .check("a", 3, MINUTE, t0 + Duration::from_secs(10))
            .unwrap_err();
        assert_eq!(wait, Duration::from_secs(50));
        assert!(limiter.check("a", 3, MINUTE, t0 + Duration::from_secs(61)).is_ok());
    }

    #[test]
    fn keys_are_independent() {
        let t0 = Instant::now();
        let mut limiter = Limiter::new(t0);
        assert!(limiter.check("a", 1, MINUTE, t0).is_ok());
        assert!(limiter.check("b", 1, MINUTE, t0).is_ok());
        assert!(limiter.check("a", 1, MINUTE, t0).is_err());
    }

    #[test]
    fn a_refused_attempt_is_not_counted() {
        // Otherwise a client that keeps trying would never get out of the window.
        let t0 = Instant::now();
        let mut limiter = Limiter::new(t0);
        assert!(limiter.check("a", 1, MINUTE, t0).is_ok());
        for i in 1..30 {
            assert!(limiter.check("a", 1, MINUTE, t0 + Duration::from_secs(i)).is_err());
        }
        assert!(limiter.check("a", 1, MINUTE, t0 + Duration::from_secs(61)).is_ok());
    }

    #[test]
    fn quiet_keys_are_forgotten() {
        let t0 = Instant::now();
        let mut limiter = Limiter::new(t0);
        for i in 0..100 {
            limiter.check(&format!("k{i}"), 1, MINUTE, t0).unwrap();
        }
        assert_eq!(limiter.len(), 100);
        // Two minutes later a new key arrives: the sweep drops the 100 that expired.
        limiter.check("fresh", 1, MINUTE, t0 + Duration::from_secs(120)).unwrap();
        assert_eq!(limiter.len(), 1);
        assert!(!limiter.is_empty());
    }

    #[test]
    fn the_step_answers_a_429_with_retry_after() {
        let scope = "test-step";
        for _ in 0..2 {
            check(scope, "someone", 2, 900).unwrap();
        }
        let error = check(scope, "someone", 2, 900).unwrap_err();
        let http = error.downcast_ref::<HttpError>().unwrap();
        assert_eq!(http.status, 429);
        let wait = http.retry_after.unwrap();
        assert!((1..=900).contains(&wait), "{wait}");
        // Another key, and another step, are not affected.
        check(scope, "someone else", 2, 900).unwrap();
        check("another-step", "someone", 2, 900).unwrap();
    }
}
